static struct ListNode *mergeTwoLists(struct ListNode *a, struct ListNode *b) {
  if (a == NULL) return b;
  if (b == NULL) return a;
  if (a->val < b->val) {
    a->next = mergeTwoLists(a->next, b);
    return a;
  }
  b->next = mergeTwoLists(a, b->next);
  return b;
}

struct ListNode *mergeKLists(struct ListNode **lists, int listsSize) {
  struct ListNode *ans = NULL;
  for (int i = 0; i < listsSize; i++) {
    ans = mergeTwoLists(ans, lists[i]);
  }
  return ans;
}

class Solution {
public:
  ListNode *mergeTwoLists(ListNode *a, ListNode *b) {
    if ((!a) || (!b)) return a ? a : b;
    ListNode head, *tail = &head, *aPtr = a, *bPtr = b;
    while (aPtr && bPtr) {
      if (aPtr->val < bPtr->val) {
        tail->next = aPtr;
        aPtr = aPtr->next;
      } else {
        tail->next = bPtr;
        bPtr = bPtr->next;
      }
      tail = tail->next;
    }
    tail->next = (aPtr ? aPtr : bPtr);
    return head.next;
  }

  ListNode *mergeKLists(vector<ListNode *> &lists) {
    ListNode *ans = nullptr;
    for (size_t i = 0; i < lists.size(); ++i) {
      ans = mergeTwoLists(ans, lists[i]);
    }
    return ans;
  }
};

func mergeTwoLists(a, b *ListNode) *ListNode {
	if a == nil {
		return b
	}
	if b == nil {
		return a
	}
	if a.Val < b.Val {
		a.Next = mergeTwoLists(a.Next, b)
		return a
	}
	b.Next = mergeTwoLists(a, b.Next)
	return b
}

func mergeKLists(lists []*ListNode) *ListNode {
	var ans *ListNode
	for _, l := range lists {
		ans = mergeTwoLists(ans, l)
	}
	return ans
}

class ListNode {
  int val;
  ListNode next;

  ListNode(int x) {
    val = x;
  }
}

class Solution {
  private ListNode mergeTwoLists(ListNode a, ListNode b) {
    if (a == null) {
      return b;
    }
    if (b == null) {
      return a;
    }
    if (a.val < b.val) {
      a.next = mergeTwoLists(a.next, b);
      return a;
    }
    b.next = mergeTwoLists(a, b.next);
    return b;
  }

  public ListNode mergeKLists(ListNode[] lists) {
    ListNode ans = null;
    for (ListNode l : lists) {
      ans = mergeTwoLists(ans, l);
    }
    return ans;
  }
}

class Solution:
    def mergeTwoLists(self, a: ListNode, b: ListNode) -> ListNode:
        if a is None:
            return b
        if b is None:
            return a
        if a.val < b.val:
            a.next = self.mergeTwoLists(a.next, b)
            return a
        b.next = self.mergeTwoLists(a, b.next)
        return b

    def mergeKLists(self, lists: List[Optional[ListNode]]) -> Optional[ListNode]:
        ans = None
        for l in lists:
            ans = self.mergeTwoLists(ans, l)
        return ans

impl Solution {
  fn merge_two_lists(
    a: Option<Box<ListNode>>,
    b: Option<Box<ListNode>>,
  ) -> Option<Box<ListNode>> {
    match (a, b) {
      (None, None) => None,
      (Some(a), None) => Some(a),
      (None, Some(b)) => Some(b),
      (Some(mut a), Some(mut b)) => {
        if a.val < b.val {
          a.next = Solution::merge_two_lists(a.next.take(), Some(b));
          Some(a)
        } else {
          b.next = Solution::merge_two_lists(Some(a), b.next.take());
          Some(b)
        }
      }
    }
  }

  pub fn merge_k_lists(lists: Vec<Option<Box<ListNode>>>) -> Option<Box<ListNode>> {
    let mut ans: Option<Box<ListNode>> = None;
    for l in lists {
      ans = Solution::merge_two_lists(ans, l);
    }
    ans
  }
}

const mergeTwoLists = (a: ListNode | null, b: ListNode | null): ListNode | null => {
  if (a === null) return b;
  if (b === null) return a;
  if (a.val < b.val) {
    a.next = mergeTwoLists(a.next, b);
    return a;
  }
  b.next = mergeTwoLists(a, b.next);
  return b;
};

const mergeKLists = (lists: Array<ListNode | null>): ListNode | null => {
  let ans: ListNode | null = null;
  for (const l of lists) {
    ans = mergeTwoLists(ans, l);
  }
  return ans;
};
